const s=a=>{if(a)return a?.toLocaleString("fa-IR")};function i(a){if(a){const e=["۰","۱","۲","۳","۴","۵","۶","۷","۸","۹"];return a.split("").map(n=>e[n]).join("")}}function u(a){const e=new Date,n=new Date(a),o=Math.floor((e-n)/1e3),r=[{max:60,value:1,name:"ثانیه"},{max:3600,value:60,name:"دقیقه"},{max:86400,value:3600,name:"ساعت"},{max:2592e3,value:86400,name:"روز"},{max:31104e3,value:2592e3,name:"ماه"},{max:1/0,value:31104e3,name:"سال"}];for(let t of r)if(o<t.max)return`${Math.floor(o/t.value)} ${t.name} پیش`}export{u as a,s as f,i as t};
